// Solix vrijgavelaag – stap 3a DROOGLOOP
// Rekent uit wat de vrijgavelaag ZOU vrijgeven. Stuurt niets aan:
// het Opta-topic en derived.* blijven ongewijzigd.
// Invoer: diagnose-payload (tweede output van 'build MQTT status JSON').
// Tekens: meter.*_w negatief = export; calc.p_batt_w positief = laden.

const ELEM_W          = 2000;  // boilerelement (bevestigd 2 kW)
const START_W         = 2200;  // Opta-startdrempel element (L1)
const STOP_W          = -300;  // besluit 21 sep (firmware nu nog 0)
const START_DELAY_S   = 20;    // firmware-startvertraging element
const MIN_ON_S        = 300;   // besluit 21 sep: min-aan 5 min
const AANBOD_TAU_S    = 30;    // EMA-tijdconstante aanbod (alleen omhoog)
const AANBOD_SLEW_WPS = 100;   // max stijging aanbod in W/s
const EMA_L1_TAU_S    = 60;    // besluit 21 sep: EMA 60 s op vrijgave L1

const clamp = (x, a, b) => Math.min(Math.max(x, a), b);
const r = (x) => Math.round(x);

const p = msg.payload;
if (!p || !p.meter || !p.batt || !p.calc) {
    node.status({fill:'red', shape:'ring', text:'payload onvolledig'});
    return null;
}
const cfg = flow.get('cfg') || {};
for (const k of ['soc_laag', 'soc_hoog', 'aanbod_max', 'i_shed']) {
    if (!Number.isFinite(cfg[k])) {
        node.status({fill:'red', shape:'ring', text:`cfg.${k} ontbreekt`});
        return null;
    }
}
if (p.opta_valid !== true) {
    // Bij ongeldige meting niets simuleren: in 3b wordt dit de fail-safe (rauw doorgeven).
    node.status({fill:'yellow', shape:'ring', text:'opta_valid=false, overgeslagen'});
    return null;
}

const now = Number(p.ts_ms) || Date.now();
const dag = new Date(now).toLocaleDateString('nl-NL', {timeZone: 'Europe/Amsterdam'});
const st = context.get('st') || {t:null, aanbod:0, ema_l1:null, on:false, t_ok:null, t_on:null, dag:null, starts:0, aan_s:0};
if (st.dag !== dag) { st.dag = dag; st.starts = 0; st.aan_s = 0; }
const dt = st.t ? clamp((now - st.t) / 1000, 0, 60) : 5;
st.t = now;

// --- k uit SoC: onder laag = +1 (batterij voorrang), boven hoog = -1 (lasten voorrang)
const soc = Number(p.batt.soc_pct);
const lo = cfg.soc_laag, hi = cfg.soc_hoog;
const k = hi > lo ? clamp(1 - 2 * (soc - lo) / (hi - lo), -1, 1) : (soc >= hi ? -1 : 1);
const alpha_vol    = (1 - k) / 2;               // modus 'volledig'
const alpha_alleen = (1 - Math.min(k, 0)) / 2;  // modus 'alleen_vrijgeven' (k in [-1,0])

// --- aanbod: laadvermogen, omhoog traag (EMA + slew), omlaag direct (veilig)
const laden = Math.max(Number(p.batt.charge_w) || 0, 0);
let aanbod;
if (laden <= st.aanbod) {
    aanbod = laden;
} else {
    const ema = st.aanbod + (dt / (AANBOD_TAU_S + dt)) * (laden - st.aanbod);
    aanbod = Math.min(ema, st.aanbod + AANBOD_SLEW_WPS * dt);
}
aanbod = clamp(aanbod, 0, cfg.aanbod_max);
st.aanbod = aanbod;

// --- F2 op totaal
const raw_exp_tot = Math.max(-p.meter.totaal_w, 0);
const sb_tot = Math.max(p.calc.surplus_bruto_w, 0);
const vrij_tot_vol    = clamp(raw_exp_tot + alpha_vol    * aanbod, 0, sb_tot);
const vrij_tot_alleen = clamp(raw_exp_tot + alpha_alleen * aanbod, 0, sb_tot);

// --- F2 op L1. Opta ziet nu: L1-export met ontlading er al af (firmware).
const ontladen = Math.max(Number(p.batt.discharge_w) || 0, 0);
const opta_l1 = Math.max(-(p.meter.fase_1_w + ontladen), 0);
const sb_l1 = Math.max(p.calc.surplus_bruto_l1_w, 0);
const vrij_l1_vol    = clamp(opta_l1 + alpha_vol    * aanbod, 0, sb_l1);
const vrij_l1_alleen = clamp(opta_l1 + alpha_alleen * aanbod, 0, sb_l1);

// --- EMA 60 s op vrijgave L1 (volledig)
st.ema_l1 = (st.ema_l1 === null) ? vrij_l1_vol
          : st.ema_l1 + (dt / (EMA_L1_TAU_S + dt)) * (vrij_l1_vol - st.ema_l1);

// --- faseguard: L1-stroom als het element erbij zou komen
const i_l1_na = Math.abs(p.meter.fase_1_w + ELEM_W) / 230;
const guard_ok = i_l1_na < cfg.i_shed;

// --- element-simulatie op EMA-signaal, stop -300 W, min-aan 5 min
const sig = st.ema_l1;
if (!st.on) {
    if (sig >= START_W && guard_ok) {
        if (st.t_ok === null) st.t_ok = now;
        if ((now - st.t_ok) / 1000 >= START_DELAY_S) {
            st.on = true; st.t_on = now; st.t_ok = null; st.starts++;
        }
    } else {
        st.t_ok = null;
    }
} else {
    st.aan_s += dt;
    const on_s = (now - st.t_on) / 1000;
    if (!guard_ok || (sig - ELEM_W < STOP_W && on_s >= MIN_ON_S)) {
        st.on = false; st.t_on = null;
    }
}
context.set('st', st);

msg.topic = 'homeassistant/Solix_Regelaar/droogloop';
msg.payload = {
    ts_ms: now,
    modus: cfg.modus,
    soc_pct: soc,
    k: Math.round(k * 100) / 100,
    alpha_vol: Math.round(alpha_vol * 100) / 100,
    alpha_alleen: Math.round(alpha_alleen * 100) / 100,
    laden_w: r(laden),
    aanbod_w: r(aanbod),
    raw_export_tot_w: r(raw_exp_tot),
    surplus_bruto_w: r(sb_tot),
    vrij_tot_vol_w: r(vrij_tot_vol),
    vrij_tot_alleen_w: r(vrij_tot_alleen),
    opta_l1_w: r(opta_l1),
    surplus_bruto_l1_w: r(sb_l1),
    vrij_l1_vol_w: r(vrij_l1_vol),
    vrij_l1_alleen_w: r(vrij_l1_alleen),
    vrij_l1_ema_w: r(st.ema_l1),
    i_l1_na_element_a: Math.round(i_l1_na * 10) / 10,
    faseguard_ok: guard_ok,
    element_sim: st.on,
    element_starts_vandaag: st.starts,
    element_aan_min_vandaag: Math.round(st.aan_s / 60)
};
node.status({fill: st.on ? 'green' : 'grey', shape:'dot',
    text:`L1 opta ${r(opta_l1)} → vrij ${r(vrij_l1_vol)} (ema ${r(st.ema_l1)}) | elem ${st.on ? 'AAN' : 'uit'} ${st.starts}x`});
return msg;
